namespace GroupSchedulerApp.Models;

// A course retrieved from Canvas.
//
// This represents imported course information, not a class meeting time.
// The user will enter meeting days, times, and semester dates separately.
public class CanvasCourse
{
    // Canvas's course ID, not an ID generated by our JSON storage.
    // Use this together with the Canvas site URL to identify a course
    // on future imports. Different Canvas sites may reuse the same IDs.
    public long CanvasCourseId { get; set; }

    // Display name shown when the user selects a course.
    public string Name { get; set; } = "";

    // Optional course code, such as "CS 2420".
    public string CourseCode { get; set; } = "";
}